#!/bin/bash
# Generated by Claude Fable 5 (Anthropic)
# Build autoware-dev-trt-a1000-fishwait7 = fishwait6 + the packages that
# instantiate header-level FISH tracepoints rebuilt against the overlay
# (GenericSubscription users: autoware_topic_state_monitor,
# autoware_pipeline_latency_monitor, autoware_topic_relay_controller,
# topic_tools) + refreshed FISH framework (LTTNG_UST_REGISTER_TIMEOUT guard).
#   - fresh container from the UNCHANGED fishwait6 image
#   - ~/fish_provenance_ros mounted (topic_tools sources at the installed version)
#   - scripts/rebuild_header_tracepoint_users.sh → /root/trace_overlay_ws
#   - committed as a NEW tag; fishwait6 stays as it is
set -euo pipefail
SRC_IMG=${SRC_IMG:-autoware-dev-trt-a1000-fishwait6:latest}
DST_IMG=${DST_IMG:-autoware-dev-trt-a1000-fishwait7:latest}
REPO=${REPO:-/home/tue037807/fish_interfere}
PROV_ROS=${PROV_ROS:-$HOME/fish_provenance_ros}
NAME=fishwait7-build
if docker image inspect "$DST_IMG" >/dev/null 2>&1; then
  echo "[build] $DST_IMG already exists — refusing to overwrite (pick another DST_IMG)"; exit 3
fi
echo "[build] $SRC_IMG → $DST_IMG"
docker rm -f $NAME >/dev/null 2>&1 || true
# the ROS-core sources are copied in (not bind-mounted) so the committed image is self-contained
docker run -d --name $NAME --net host "$SRC_IMG" bash -c 'sleep 7200' >/dev/null
trap 'docker rm -f $NAME >/dev/null 2>&1 || true' EXIT
docker exec $NAME rm -rf /root/fish_interfere
docker cp "$REPO" $NAME:/root/fish_interfere
docker exec $NAME mkdir -p /opt/fish_provenance_ros
docker cp "$PROV_ROS/src" $NAME:/opt/fish_provenance_ros/src
docker cp "$PROV_ROS/tags" $NAME:/opt/fish_provenance_ros/tags
docker cp "$PROV_ROS/versions.json" $NAME:/opt/fish_provenance_ros/versions.json
docker exec $NAME bash -lc '
  set -e
  source /opt/ros/humble/setup.bash; source /opt/autoware/setup.bash; source /root/trace_overlay_ws/install/setup.bash
  cd /root/fish_interfere
  echo "[build] refreshing FISH framework (wrapper + python + ini; overlay untouched)"
  FISH_SETUP_PARENT=1 source scripts/install_fish.sh 2>&1 | tail -3
  grep -c "LTTNG_UST_REGISTER_TIMEOUT" /root/fish/bin/ros2 && echo "[build] register-timeout guard present in ros2 wrapper"
  bash scripts/rebuild_header_tracepoint_users.sh 2>&1 | tee /root/rebuild_header_tracepoint_users.log | grep -E "^\[rebuild\]|error|Error" | head -40
  cat /root/trace_overlay_ws/fish_rebuilt_packages.json
'
echo "[build] committing $DST_IMG"
docker commit -m "fishwait6 + GenericSubscription users rebuilt against the FISH overlay (topic_state_monitor, pipeline_latency_monitor, topic_relay_controller, topic_tools) + LTTNG_UST_REGISTER_TIMEOUT guard; /opt/fish_provenance_ros baked in" $NAME "$DST_IMG"
docker image inspect "$DST_IMG" --format '[build] done: {{.RepoTags}} {{.Size}} bytes'
